-- 0275 — Academy : cours « Les introductions en bourse (IPO) à la BRVM » publié
-- en remplacement du cours « L’introduction en bourse de Dangote : un cas
-- pratique, hors BRVM » (2026-11-26, décision de l’exploitant).
--
-- Nouvelle adresse : /formations/academy/introduction-en-bourse-ipo-brvm
-- (l’ancienne contenait « dangote » et portait un autre sujet).
-- Source : frontend/lib/academy/contenus/autres/introduction-en-bourse-ipo-brvm.json, testé par
-- ipo-brvm.test.ts (schéma, conformité, aucun site tiers cité, arithmétique,
-- et égalité stricte entre ce fichier et le contenu ci-dessous).
--
-- Choix éditoriaux : faits tirés de la BRVM, de la BVMAC, du gouvernement du
-- Bénin et du dépliant d’offre de BGFI Holding ; tout le reste est un calcul
-- annoncé comme tel. Exemples de valorisation sur une banque FICTIVE. Pas de
-- partie d’actualité (OPV Coris) : elle serait périmée dès janvier 2027.
--
-- Le cours Dangote est DÉPUBLIÉ, pas supprimé (modèle 0242) : son contenu reste
-- en base et dans le dépôt ; repasser `published` à true suffit à le republier.
-- Sa progression (academy_progress) n’est pas touchée.
--
-- Aucun déploiement préalable requis : le contenu n’utilise que des blocs déjà
-- acceptés par courseContentSchema. Aucune donnée personnelle. Idempotent :
-- l’insertion ne fait rien si le slug existe, la dépublication ne touche qu’un
-- cours encore publié.

insert into public.academy_courses (slug, titre, niveau, resume, content, html, published)
values (
  $wb$introduction-en-bourse-ipo-brvm$wb$,
  $wb$Les introductions en bourse (IPO) à la BRVM : du visa à la première cotation$wb$,
  $wb$debutant$wb$,
  $wb$Le mécanisme d’une introduction en bourse à la BRVM : conditions d’admission, huit étapes, souscription et frais, prix (PER, P/B), marché avant et après. Quatre cas réels et le contre-exemple BGFI.$wb$,
  $wb${"titre":"Les introductions en bourse (IPO) à la BRVM : du visa à la première cotation","niveau":"debutant","intro":"Une introduction en bourse ouvre le capital d’une société au public, puis fait coter ses actions. À la BRVM, l’opération reste rare : quatre sociétés seulement ont rejoint la cote depuis 2020, Orange Côte d’Ivoire, la Loterie Nationale du Bénin, la BIIC et Bridge Bank Group Côte d’Ivoire.\n\nCe cours explique ce qu’est une introduction en bourse, les conditions pour être coté, le déroulé en huit étapes, la souscription et ses frais, la façon dont se fixe le prix, et le comportement du marché avant et après. Il s’appuie sur ces quatre opérations réelles et sur un contre-exemple en Afrique centrale, BGFI Holding.\n\nLes faits viennent de la BRVM, de la BVMAC, du gouvernement du Bénin et des documents d’offre ; les calculs sont signalés comme tels. Les exemples de valorisation portent sur une banque fictive. Faits arrêtés au 26 novembre 2026.","relatedLinks":[{"label":"Comprendre le PER et la valorisation à la BRVM","slug":"comprendre-le-per-et-la-valorisation-a-la-brvm"},{"label":"Études de cas réels de la BRVM","slug":"etudes-de-cas-reels-brvm"}],"lessons":[{"titre":"Leçon 1 — Qu’est-ce qu’une introduction en bourse ?","module":"Module 1 — Comprendre l’opération","categorie":"general","duree_min":10,"sous_titre":"OPV ou augmentation de capital : qui vend, qui encaisse, qui voit sa part diminuer.","resume":"Une introduction en bourse ouvre le capital d’une société au public, puis fait coter ses actions. À la BRVM, l’opération reste rare : quatre sociétés seulement ont rejoint la cote depuis 2020.","avertissement":"Ceci n’est pas un conseil en investissement. Investir en actions comporte un risque de perte en capital. Faits arrêtés au 26 novembre 2026.","sections":[{"type":"definition","titre":"Définition","contenu":"Une introduction en bourse (en anglais IPO, Initial Public Offering) est l’opération par laquelle une société propose ses actions au public, puis les fait coter en bourse. Dans l’UEMOA, la cotation a lieu à la BRVM, la bourse commune aux huit pays de l’Union.\nL’offre prend l’une de deux formes, et la différence décide qui reçoit l’argent. Dans une offre publique de vente (OPV), des actionnaires existants vendent des actions qui existent déjà : l’argent va aux vendeurs, pas à la société. Dans une augmentation de capital, la société crée des actions nouvelles et encaisse elle-même l’argent.","flux":[{"titre":"La société","detail":"Elle décide d’ouvrir son capital.","icone":"entreprise"},{"titre":"Le régulateur","detail":"L’AMF-UMOA vise la note d’information.","icone":"decision"},{"titre":"Les épargnants","detail":"Ils souscrivent au prix fixé.","icone":"actionnaires"},{"titre":"La bourse","detail":"Les actions sont cotées à la BRVM.","icone":"graphique"}]},{"type":"importance","titre":"Un événement rare à la BRVM","contenu":"Depuis 2020, quatre sociétés seulement sont entrées à la cote de la BRVM : Orange Côte d’Ivoire en 2022, la Loterie Nationale du Bénin en 2024, la BIIC en 2025 et Bridge Bank Group Côte d’Ivoire en 2026. Selon la BRVM, ces quatre opérations ont mobilisé 352,13 milliards FCFA au total.\nPour la société, l’entrée en bourse apporte de la visibilité, un accès durable aux investisseurs et des exigences de transparence. Pour l’épargnant, c’est l’occasion d’acheter des actions à un prix fixé à l’avance, identique pour tous les souscripteurs d’une même catégorie.","stats":[{"label":"Introductions depuis 2020","valeur":"4","detail":"Orange CI, LNB, BIIC, Bridge Bank Group CI"},{"label":"Montant mobilisé par ces quatre offres","valeur":"352,13 Md FCFA","detail":"Source : BRVM, septembre 2026"},{"label":"Poids des banques dans la capitalisation des actions","valeur":"42,94 %","detail":"Au 22 septembre 2026, source : BRVM"}]},{"type":"lexique","titre":"Le vocabulaire à connaître","contenu":"Ces termes reviennent dans toutes les leçons de ce cours.","tableau":{"colonnes":["Terme","Ce que cela veut dire"],"lignes":[["Note d’information","Le prospectus de l’offre : activité, comptes, prix, calendrier, règles d’allocation, facteurs de risque. C’est le document de référence de l’épargnant."],["Visa de l’AMF-UMOA","L’autorisation du régulateur de l’UMOA. Sans visa, aucune offre ne peut être proposée au public."],["SGI","Société de gestion et d’intermédiation : l’intermédiaire agréé par lequel on achète et vend des titres. Une SGI « arrangeur et chef de file » pilote l’offre, les autres forment le syndicat de placement."],["Flottant","La part du capital détenue par le public. La BRVM impose un minimum selon le compartiment."],["Taux de souscription","La demande reçue divisée par l’offre. Au-delà de 100 %, l’offre est sursouscrite et les demandes sont réduites."],["Clôture anticipée","Fin de la souscription avant la date prévue, lorsque toute l’offre a trouvé preneur."],["Cours de référence","Le prix de départ de la première séance, en général égal au prix de l’offre."],["DC/BR","Le Dépositaire central / Banque de règlement : il tient les comptes de titres et règle les opérations du marché."]],"note":""}},{"type":"piege","titre":"Trois notions souvent confondues","contenu":"Ces confusions faussent la lecture d’une introduction en bourse.","points":[{"titre":"La dilution","detail":"Dans une augmentation de capital, les actions nouvelles réduisent la part de chaque actionnaire existant. En échange, l’argent entre dans les fonds propres : pour une banque, cela renforce sa solvabilité. Une OPV ne dilue personne, mais n’apporte rien au bilan de la société."},{"titre":"Le prix d’une action et sa cherté","detail":"Une action à 80 000 FCFA n’est pas forcément plus chère qu’une action à 4 800 FCFA. La cherté se mesure en rapportant le prix au bénéfice ou aux fonds propres par action (leçon 5)."},{"titre":"Une offre annoncée et une offre autorisée","detail":"Une société peut annoncer un projet d’introduction des mois à l’avance. Seul un prospectus visé par le régulateur ouvre une offre au public."}]},{"type":"retenir","titre":"À retenir","contenu":"Une introduction en bourse = une offre au public puis une cotation. Dans une OPV, l’argent va aux vendeurs ; dans une augmentation de capital, il va à la société, au prix d’une dilution des anciens actionnaires.","encadres":[{"ton":"cle","titre":"La question à poser en premier","texte":"Qui vend, et qui reçoit l’argent ? La réponse figure dans la note d’information, à la rubrique décrivant l’opération."}]}],"quiz":[{"question":"Dans une offre publique de vente (OPV), qui reçoit l’argent des souscripteurs ?","options":["La société introduite en bourse, pour financer sa croissance","Les actionnaires qui vendent leurs actions","La BRVM","Le régulateur"],"correct":1,"explication":"Une OPV porte sur des actions existantes : le produit de la vente revient aux actionnaires vendeurs. La société ne reçoit pas d’argent frais."},{"question":"Quel effet une augmentation de capital a-t-elle sur les actionnaires déjà présents ?","options":["Aucun effet","Leur part du capital diminue","Leur part du capital augmente","Ils sont remboursés"],"correct":1,"explication":"Les actions nouvelles s’ajoutent aux anciennes : chaque actionnaire existant détient une part plus petite du capital. C’est la dilution."},{"question":"Combien de sociétés sont entrées à la cote de la BRVM depuis 2020, selon la BRVM ?","options":["Deux","Quatre","Dix","Vingt"],"correct":1,"explication":"Orange Côte d’Ivoire (2022), la Loterie Nationale du Bénin (2024), la BIIC (2025) et Bridge Bank Group Côte d’Ivoire (2026)."},{"question":"Quel document l’épargnant doit-il lire avant de souscrire ?","options":["Un article de presse","La note d’information visée par l’AMF-UMOA","Un message d’une SGI reçu sur les réseaux sociaux","Le dernier bulletin de la cote"],"correct":1,"explication":"La note d’information, visée par le régulateur, décrit l’offre, ses risques et ses règles. Les autres sources ne la remplacent pas."}],"liens":[{"label":"Voir les cours des actions de la BRVM","href":"/actions"}]},{"titre":"Leçon 2 — Les conditions pour être coté à la BRVM","module":"Module 1 — Comprendre l’opération","categorie":"regulatory","duree_min":8,"sous_titre":"Trois compartiments, trois niveaux d’exigence.","resume":"Toute société candidate doit être une société anonyme. Le reste dépend du compartiment visé : Prestige, Principal ou Croissance.","avertissement":"Ceci n’est pas un conseil en investissement. Investir en actions comporte un risque de perte en capital. Faits arrêtés au 26 novembre 2026.","sections":[{"type":"definition","titre":"Les trois compartiments du marché des actions","contenu":"La BRVM classe les sociétés cotées en trois compartiments. Plus le compartiment est exigeant, plus la société doit être grande, ancienne et transparente. Bridge Bank Group Côte d’Ivoire a été admise au compartiment Prestige en septembre 2026.","tableau":{"colonnes":["Critère","Prestige","Principal","Croissance"],"lignes":[["Capital social minimum","100 millions FCFA","100 millions FCFA","10 millions FCFA"],["Capitalisation minimale","50 milliards FCFA","1 milliard FCFA","100 millions FCFA"],["Ancienneté d’activité","10 ans","5 ans","2 ans"],["Comptes certifiés","5 ans","3 ans","2 ans"],["Flottant minimum","20 %, au moins 4 millions de titres et 200 actionnaires","15 %, au moins 2 millions de titres et 100 actionnaires","10 %, au moins 500 000 titres"],["Bénéfices","3 exercices bénéficiaires sur les 5 derniers","Capacité à être profitable, prouvée et documentée","Non requis"],["Gouvernance aux normes UEMOA","Obligatoire","Obligatoire","Non requis"],["Convention d’animation de marché","Oui","Oui","Non"],["Business plan et listing sponsor","Non","Non","Oui"]],"note":"Source : BRVM, conditions d’admission au marché des actions (brvm.org)."}},{"type":"importance","titre":"Ce que la cotation exige ensuite","contenu":"Une fois cotée, la société s’engage à publier régulièrement son information financière. C’est ce qui permet à l’actionnaire de suivre son investissement.","points":[{"titre":"Comptes annuels","detail":"Dans les 4 mois suivant la clôture de l’exercice, et au moins 15 jours avant l’assemblée générale ordinaire."},{"titre":"Comptes semestriels","detail":"Dans les 4 mois suivant la fin du premier semestre, avec l’attestation des commissaires aux comptes."},{"titre":"Commentaire trimestriel","detail":"Un mois après chaque trimestre, pour les compartiments Prestige et Principal."}]},{"type":"retenir","titre":"À retenir","contenu":"Les critères d’admission protègent l’épargnant : taille, ancienneté, comptes certifiés, flottant minimum. Ils ne garantissent ni la qualité de l’investissement ni l’évolution du cours.","encadres":[{"ton":"attention","titre":"Une cotation n’est pas un label de rentabilité","texte":"Être admis au Prestige prouve qu’une société remplit des critères à une date donnée. Le cours dépendra ensuite de ses résultats, que personne ne connaît à l’avance."}]}],"quiz":[{"question":"Quelle capitalisation minimale le compartiment Prestige exige-t-il ?","options":["1 milliard FCFA","50 milliards FCFA","100 millions FCFA","500 milliards FCFA"],"correct":1,"explication":"Le Prestige exige 50 milliards FCFA de capitalisation ; le Principal 1 milliard ; le Croissance 100 millions."},{"question":"Quel compartiment est conçu pour les PME en croissance ?","options":["Prestige","Principal","Croissance","Obligataire"],"correct":2,"explication":"Le compartiment Croissance a des seuils plus bas et exige un business plan et un listing sponsor."},{"question":"Dans quel délai une société cotée publie-t-elle ses comptes semestriels ?","options":["Une semaine","Un mois","Quatre mois après la fin du semestre","Deux ans"],"correct":2,"explication":"Les comptes semestriels sont publiés dans les 4 mois suivant la fin du premier semestre."}]},{"titre":"Leçon 3 — Le déroulé en 8 étapes","module":"Module 2 — De la décision à la cotation","categorie":"regulatory","duree_min":10,"sous_titre":"Qui fait quoi, et dans quel ordre.","resume":"De la décision de la société à la première séance de cotation, une introduction en bourse suit huit étapes. Chacune est illustrée par une opération réelle.","avertissement":"Ceci n’est pas un conseil en investissement. Investir en actions comporte un risque de perte en capital. Faits arrêtés au 26 novembre 2026.","sections":[{"type":"definition","titre":"Les 8 étapes d’une introduction à la BRVM","contenu":"L’ordre est toujours le même. Seules les durées changent d’une opération à l’autre.","etapes":[{"titre":"1. La décision","detail":"L’assemblée générale extraordinaire décide l’introduction. Pour une entreprise publique, c’est l’État qui décide de céder une partie de ses actions."},{"titre":"2. La préparation","detail":"La société choisit sa SGI arrangeur et chef de file, met ses comptes et sa gouvernance aux normes, fait évaluer l’entreprise, fixe le prix et rédige la note d’information. EDC Investment Corporation a arrangé les offres de la Loterie Nationale du Bénin et de la BIIC ; Bridge Securities celle de Bridge Bank Group Côte d’Ivoire."},{"titre":"3. Le visa de l’AMF-UMOA","detail":"Le régulateur examine la note d’information et délivre un visa. L’offre de la Loterie Nationale du Bénin a reçu le visa n° OA/24-01 du 19 août 2024.","cle":true},{"titre":"4. L’admission à la BRVM","detail":"La SGI arrangeur dépose la demande d’admission et le compartiment visé."},{"titre":"5. La souscription","detail":"Après une campagne d’information, l’offre est placée par un syndicat de SGI dans toute l’UEMOA. Elle peut être close avant la date prévue : celle d’Orange Côte d’Ivoire, prévue du 5 au 19 décembre 2022, a été close par anticipation."},{"titre":"6. L’allocation","detail":"Les demandes sont centralisées puis servies selon les règles de chaque catégorie d’investisseurs (leçon 4)."},{"titre":"7. Le règlement-livraison","detail":"Le DC/BR inscrit les actions sur les comptes-titres des souscripteurs ; les vendeurs, ou la société en cas d’augmentation de capital, reçoivent les fonds."},{"titre":"8. La première cotation","detail":"La BRVM publie un avis, puis ouvre la première séance. Le cours de référence est le prix de l’offre ; le premier cours sort de la confrontation des ordres d’achat et de vente.","cle":true}]},{"type":"cas","titre":"Combien de temps cela prend : quatre exemples","contenu":"Entre l’ouverture de la souscription et la première cotation, il s’écoule de quelques semaines à quelques mois.","reel":true,"tableau":{"colonnes":["Société","Souscription","Première cotation"],"lignes":[["Orange Côte d’Ivoire","5 au 19 décembre 2022, close par anticipation","30 décembre 2022"],["Loterie Nationale du Bénin","7 au 25 octobre 2024","13 décembre 2024"],["BIIC","13 janvier au 28 février 2025","28 avril 2025"],["Bridge Bank Group Côte d’Ivoire","Non reprise ici","24 septembre 2026"]],"note":"Sources : BRVM (communiqués et avis de première cotation), gouvernement du Bénin (communiqués de l’État sur les offres LNB et BIIC)."}},{"type":"piege","titre":"Le raccourci à éviter","contenu":"Une introduction annoncée dans la presse n’est pas une offre ouverte. Tant que le visa de l’AMF-UMOA n’est pas délivré, personne ne peut vous demander d’argent pour souscrire. Toute sollicitation hors des SGI agréées est à vérifier auprès de l’AMF-UMOA et de la BRVM avant le moindre versement."},{"type":"retenir","titre":"À retenir","contenu":"Décision, préparation, visa, admission, souscription, allocation, règlement-livraison, première cotation. Le visa est le moment qui rend l’offre réelle ; la première cotation, celui où le marché fixe librement le prix."}],"quiz":[{"question":"Quelle étape rend une offre légalement ouverte au public ?","options":["L’annonce de l’opération dans la presse économique régionale","Le visa de l’AMF-UMOA sur la note d’information","La première cotation","Le choix de la SGI"],"correct":1,"explication":"Sans visa du régulateur, aucune offre ne peut être proposée au public."},{"question":"Le jour de la première cotation, quel est en général le cours de référence ?","options":["Le prix de l’offre","Zéro","Le cours d’une société comparable","Un prix choisi par la SGI ce jour-là"],"correct":0,"explication":"Le cours de référence est le prix de l’offre ; le premier cours sort ensuite de la confrontation des ordres."},{"question":"Qui inscrit les actions sur les comptes-titres des souscripteurs ?","options":["L’AMF-UMOA","Le DC/BR","La société introduite","Le gouvernement"],"correct":1,"explication":"Le Dépositaire central / Banque de règlement tient les comptes de titres et règle les opérations."},{"question":"L’offre d’Orange Côte d’Ivoire était prévue du 5 au 19 décembre 2022. Que s’est-il passé ?","options":["Elle a été annulée","Elle a été prolongée d’un mois","Elle a été close par anticipation","Elle a été réservée à l’État"],"correct":2,"explication":"Toute l’offre a trouvé preneur avant la date prévue : la souscription a été close par anticipation."}]},{"titre":"Leçon 4 — Souscrire : démarche, allocation, frais","module":"Module 2 — De la décision à la cotation","categorie":"income","duree_min":12,"sous_titre":"Ce que coûte une souscription, et pourquoi on n’obtient pas toujours ce qu’on demande.","resume":"On souscrit par une SGI, pendant la période prévue, au prix fixé. En cas de forte demande, les demandes sont réduites ; frais et impôts réduisent ensuite le gain.","avertissement":"Ceci n’est pas un conseil en investissement. Investir en actions comporte un risque de perte en capital. Faits arrêtés au 26 novembre 2026.","sections":[{"type":"definition","titre":"La démarche, pas à pas","contenu":"Toutes les SGI agréées de l’UEMOA peuvent en général recevoir les souscriptions, pas seulement le chef de file.","etapes":[{"titre":"Ouvrir un compte-titres","detail":"Auprès d’une SGI agréée, dans n’importe quel pays de l’UEMOA."},{"titre":"Lire la note d’information","detail":"Prix, nombre d’actions, catégories d’investisseurs, règles d’allocation, calendrier, politique de dividende."},{"titre":"Approvisionner le compte","detail":"Nombre d’actions × prix, plus les frais de la SGI."},{"titre":"Remettre le bulletin de souscription","detail":"Signé, avec les justificatifs demandés. Mieux vaut le faire tôt : la souscription peut être close par anticipation."},{"titre":"Recevoir les actions","detail":"Après l’allocation et le règlement-livraison ; elles deviennent négociables le jour de la première cotation.","cle":true}]},{"type":"cas","titre":"L’allocation : deux mécanismes (exemple fictif)","contenu":"Prenons une offre de la banque fictive « Banque Alpha » à 8 000 FCFA l’action. La demande atteint 200 % de l’offre, et vous demandez 100 actions, soit 800 000 FCFA versés.\nLes règles exactes, qui peuvent aussi réserver des tranches à certaines catégories (salariés, personnes d’un pays donné), figurent dans la note d’information.","points":[{"titre":"Prorata pur","detail":"Chacun reçoit la moitié de sa demande : vous obtenez 50 actions, et 400 000 FCFA vous sont rendus."},{"titre":"Part irréductible, puis prorata","detail":"Chaque demande est d’abord servie en entier jusqu’à un seuil, par exemple 20 actions, puis le reste de l’offre est réparti. Vous obtenez ces 20 actions plus une part du reste : les petites demandes sont mieux servies."}],"encadres":[{"ton":"attention","titre":"Le coût de l’argent immobilisé","texte":"Entre le versement et le remboursement du trop-versé, votre argent est bloqué plusieurs semaines sans rapporter. Plus la demande est forte, plus la part immobilisée pour rien est grande."}]},{"type":"importance","titre":"Frais et impôts : ce qui réduit le gain","contenu":"À chaque achat ou revente sur le marché, la SGI prélève une commission, à laquelle s’ajoutent les commissions de la BRVM et du DC/BR : comptez de l’ordre de 1 à 1,5 % selon la SGI. Les dividendes subissent un impôt retenu à la source, l’IRVM, dont le taux dépend du pays de la société : en Côte d’Ivoire, 12 % pour les personnes physiques et 10 % pour les personnes morales depuis 2025.","simulation":{"type":"frais_ordre","consigne":"Saisissez le taux de frais de votre SGI : le simulateur calcule le coût de l’ordre et la hausse nécessaire pour simplement retrouver votre mise.","cours":8000,"quantite":100,"taux_frais_pct":1.3,"minimum_fcfa":0}},{"type":"retenir","titre":"À retenir","contenu":"On ne reçoit pas toujours ce qu’on demande : en cas de sursouscription, les demandes sont réduites. Et un gain affiché se lit toujours frais et impôts déduits."}],"quiz":[{"question":"Une offre est souscrite à 200 % avec réduction proportionnelle. Vous avez demandé 100 actions. Combien en recevez-vous ?","options":["100","50","200","Aucune"],"correct":1,"explication":"Avec un prorata pur, chacun reçoit la moitié de sa demande : 100 ÷ 2 = 50 actions."},{"question":"Pourquoi une « part irréductible » avantage-t-elle les petites demandes ?","options":["Parce qu’elles sont payées à un prix réduit, réservé aux particuliers de l’UEMOA","Parce que chaque demande est d’abord servie en entier jusqu’à un seuil","Parce qu’elles passent avant les salariés","Parce qu’elles échappent aux frais"],"correct":1,"explication":"Toutes les demandes reçoivent d’abord une part garantie ; une petite demande peut donc être servie en totalité."},{"question":"Quel est le taux d’IRVM sur les dividendes d’une société cotée ivoirienne pour une personne physique, depuis 2025 ?","options":["0 %","5 %","12 %","30 %"],"correct":2,"explication":"12 % pour les personnes physiques, 10 % pour les personnes morales."},{"question":"Pourquoi souscrire tôt pendant la période d’offre ?","options":["Le prix baisse chaque jour","La souscription peut être close par anticipation","Les frais sont plus bas le premier jour","La loi l’impose"],"correct":1,"explication":"Une offre très demandée peut fermer avant la date prévue : une demande déposée trop tard n’est pas prise."}]},{"titre":"Leçon 5 — Comment se fixe le prix : PER, P/B, dividende","module":"Module 3 — Évaluer et suivre","categorie":"evaluation","duree_min":14,"sous_titre":"Trois ratios pour juger si le prix de l’offre est raisonnable.","resume":"L’arrangeur évalue la société, puis fixe un prix assez attractif pour que l’offre soit souscrite. Trois ratios permettent à l’épargnant de refaire le calcul : le PER, le P/B et le rendement du dividende.","avertissement":"Ceci n’est pas un conseil en investissement. Investir en actions comporte un risque de perte en capital. Faits arrêtés au 26 novembre 2026.","sections":[{"type":"definition","titre":"Le PER : combien d’années de bénéfice on paie","contenu":"On évalue surtout une banque de deux façons : en la comparant aux banques déjà cotées (multiples de bénéfice ou de fonds propres), et en actualisant les dividendes qu’elle versera. La méthode la plus simple à refaire soi-même est le PER (price earning ratio).","formules":[{"nom":"Valorisation au prix de l’offre","expression":"Prix par action × Nombre total d’actions","exemple":"Banque Alpha (fictive) : 8 000 FCFA × 40 millions d’actions = 320 milliards FCFA."},{"nom":"PER","expression":"Valorisation ÷ Résultat net (ou prix ÷ bénéfice par action)","exemple":"320 milliards ÷ 25 milliards de bénéfice = 12,8 : l’acheteur paie 12,8 années du bénéfice actuel."}],"simulation":{"type":"per","consigne":"Modifiez le prix ou le bénéfice par action ; en mode données réelles, comparez avec des sociétés cotées.","cours":8000,"bpa":625,"croissance_pct":0,"annees":3,"codes":["ORAC","SGBC","ECOC"]}},{"type":"importance","titre":"Pour une banque, le P/B et le dividende comptent autant","contenu":"Le P/B (price to book) compare la valorisation aux fonds propres. Il est lié au PER par la rentabilité des fonds propres (ROE) : P/B = PER × ROE. Le rendement du dividende rapporte le dividende annuel au prix payé.","formules":[{"nom":"P/B","expression":"Valorisation ÷ Fonds propres = PER × ROE","exemple":"Banque Alpha : fonds propres de 125 milliards, ROE de 20 % ; P/B = 320 ÷ 125 = 2,56, soit 12,8 × 0,20."},{"nom":"Rendement du dividende","expression":"Dividende par action ÷ Prix payé","exemple":"Banque Alpha distribue la moitié de son bénéfice : 12,5 milliards ÷ 40 millions = 312,5 FCFA par action, soit 3,9 % du prix brut, 3,4 % après 12 % d’IRVM (275 FCFA)."}],"simulation":{"type":"pb_roe","consigne":"Comparez deux banques fictives : à PER égal, la plus rentable vaut plus cher en fonds propres.","societes":[{"nom":"Banque Alpha","per":12.8,"roe_pct":20},{"nom":"Banque Bêta","per":12.8,"roe_pct":12}],"codes":[]}},{"type":"piege","titre":"Le prix d’une action ne dit pas si elle est chère","contenu":"Une action à 80 000 FCFA peut être moins chère qu’une action à 4 800 FCFA. Tout dépend du bénéfice et des fonds propres par action. Exemple : la banque A cote 5 000 FCFA pour un bénéfice par action de 250 FCFA (PER 20) ; la banque B cote 40 000 FCFA pour 4 000 FCFA de bénéfice par action (PER 10). B est deux fois moins chère que A, malgré un prix unitaire huit fois plus élevé.\nLe prix unitaire compte pour l’accès, pas pour la valeur : une seule action à 80 000 FCFA empêche un petit épargnant de fractionner son ordre ou de diversifier."},{"type":"cas","titre":"La décote réservée aux salariés","contenu":"Les offres prévoient souvent une tranche réservée au personnel, à prix réduit, pour associer les salariés au capital. Si Banque Alpha accordait 20 % de décote, ses salariés paieraient 6 400 FCFA au lieu de 8 000. C’est pourquoi le montant total d’une offre est légèrement inférieur au nombre d’actions multiplié par le prix public."},{"type":"retenir","titre":"À retenir","contenu":"Prix × nombre d’actions = valorisation ; valorisation ÷ bénéfice = PER ; PER × ROE = P/B. Un PER s’interprète face à celui des sociétés comparables, jamais seul."}],"quiz":[{"question":"La banque A cote 5 000 FCFA pour un bénéfice par action de 250 FCFA ; la banque B cote 40 000 FCFA pour 4 000 FCFA. Laquelle est la moins chère selon le PER ?","options":["La banque A","La banque B","Elles se valent","On ne peut pas le savoir"],"correct":1,"explication":"PER de A = 5 000 ÷ 250 = 20 ; PER de B = 40 000 ÷ 4 000 = 10. B est moins chère, malgré un prix unitaire huit fois plus élevé."},{"question":"Une banque a un PER de 12 et une rentabilité des fonds propres de 15 %. Quel est son P/B ?","options":["0,8","1,8","12,15","27"],"correct":1,"explication":"P/B = PER × ROE = 12 × 0,15 = 1,8."},{"question":"Une société de 40 millions d’actions est offerte à 8 000 FCFA. Quelle est sa valorisation ?","options":["32 milliards FCFA","320 milliards FCFA","3 200 milliards FCFA","8 milliards FCFA"],"correct":1,"explication":"8 000 × 40 000 000 = 320 000 000 000 FCFA, soit 320 milliards."},{"question":"Pourquoi le montant total d’une offre est-il souvent un peu inférieur au nombre d’actions multiplié par le prix public ?","options":["Parce que la BRVM prélève une taxe","Parce qu’une tranche est vendue aux salariés avec une décote","Parce que le prix baisse pendant l’offre","Parce que la BRVM et l’AMF-UMOA prélèvent une partie du montant levé"],"correct":1,"explication":"La tranche réservée au personnel est vendue moins cher que le prix public."}]},{"titre":"Leçon 6 — Le marché avant, pendant et après l’introduction","module":"Module 3 — Évaluer et suivre","categorie":"technical","duree_min":12,"sous_titre":"Demande forte, hausse plafonnée, puis retour aux résultats.","resume":"À la BRVM, une introduction suit souvent le même scénario : une demande forte pendant la souscription, une hausse limitée à 7,5 % par séance les premiers jours, puis un cours qui suit les résultats de la société, à la hausse comme à la baisse.","avertissement":"Ceci n’est pas un conseil en investissement. Investir en actions comporte un risque de perte en capital. Faits arrêtés au 26 novembre 2026.","sections":[{"type":"definition","titre":"Avant et pendant l’offre","contenu":"À la BRVM, le prix est fixé à l’avance dans la note d’information : tous les souscripteurs d’une même catégorie paient le même prix, quelle que soit la demande. Pour souscrire, certains investisseurs vendent d’autres actions, ce qui peut peser sur le reste du marché.\nQuand l’offre est jugée attractive, elle est vite couverte et les souscripteurs sont servis en partie. Ceux qui n’ont pas obtenu assez d’actions achètent alors le jour de la cotation, ce qui alimente la demande des premières séances."},{"type":"importance","titre":"Le jour J : la « réservation » à +7,5 %","contenu":"Le cours d’une action ne peut pas varier de plus de 7,5 % par séance autour de son cours de référence. Quand il n’y a presque que des acheteurs, le titre reste bloqué à la limite haute : il est « réservé à la hausse », peu d’actions s’échangent, et cela peut durer plusieurs séances.\nOrange Côte d’Ivoire en offre l’exemple : pour un cours de référence de 9 500 FCFA, le premier cours s’est établi à 10 210 FCFA, soit +7,47 %, presque la limite (source : BRVM, 30 décembre 2022).","stats":[{"label":"Cours de référence d’Orange CI","valeur":"9 500 FCFA","detail":"Prix de l’offre, 30 décembre 2022"},{"label":"Premier cours","valeur":"10 210 FCFA","detail":"+7,47 % à la première séance"},{"label":"Limite de variation par séance","valeur":"±7,5 %","detail":"Autour du cours de référence"}]},{"type":"cas","titre":"Après : comparez le cours du jour au prix de l’offre","contenu":"Passée l’euphorie, le cours suit les bénéfices et les dividendes. Le tableau ci-dessous affiche le dernier cours de quatre sociétés introduites depuis 2022, lu chaque jour dans la base WESTBOURSE. Comparez-le à leur prix d’introduction.","reel":true,"tableau":{"colonnes":["Société","Code","Prix de l’offre","Première cotation"],"lignes":[["Orange Côte d’Ivoire","ORAC","9 500 FCFA","30 décembre 2022"],["Loterie Nationale du Bénin","LNBB","4 800 FCFA","13 décembre 2024"],["BIIC","BICB","5 250 FCFA","28 avril 2025"],["Bridge Bank Group Côte d’Ivoire","BBGC","6 750 FCFA","24 septembre 2026"]],"note":"Prix de l’offre : BRVM (cours de référence d’Orange CI et de Bridge Bank Group CI), gouvernement du Bénin (LNB, BIIC)."},"donnees_reelles":{"vue":"cours","codes":["ORAC","LNBB","BICB","BBGC"]},"encadres":[{"ton":"info","titre":"Comment lire l’écart","texte":"Écart = (cours du jour − prix de l’offre) ÷ prix de l’offre. L’écart ne compte pas les dividendes perçus depuis l’introduction, qui améliorent le résultat réel de l’actionnaire. Le 25 novembre 2026, une seule des quatre cotait sous son prix d’offre : la Loterie Nationale du Bénin."}]},{"type":"retenir","titre":"À retenir","contenu":"Une introduction bien reçue garantit rarement plus que quelques séances de hausse. Ensuite, c’est l’entreprise qui fait le cours : ses bénéfices, ses dividendes, sa croissance."}],"quiz":[{"question":"De combien le cours d’une action peut-il varier au plus en une séance à la BRVM ?","options":["±2 %","±7,5 %","±20 %","Sans limite"],"correct":1,"explication":"La BRVM encadre la variation quotidienne à ±7,5 % autour du cours de référence."},{"question":"Que signifie qu’une action est « réservée à la hausse » ?","options":["La BRVM a suspendu sa cotation","Le cours est bloqué à la limite haute, faute de vendeurs","Seuls les salariés de la société peuvent l’acheter pendant la séance","Son prix a été fixé par l’État"],"correct":1,"explication":"Les acheteurs sont bien plus nombreux que les vendeurs : le cours plafonne à +7,5 % et peu de titres s’échangent."},{"question":"Orange Côte d’Ivoire avait un cours de référence de 9 500 FCFA et un premier cours de 10 210 FCFA. Quelle est la hausse ?","options":["+0,7 %","+7,47 %","+10,2 %","+75 %"],"correct":1,"explication":"(10 210 − 9 500) ÷ 9 500 = 0,0747, soit +7,47 %."},{"question":"Pourquoi l’écart entre le cours du jour et le prix de l’offre sous-estime-t-il souvent le résultat réel de l’actionnaire ?","options":["Parce qu’il ne compte pas les dividendes perçus","Parce qu’il compte deux fois les frais","Parce que le prix de l’offre change chaque année","Il ne le sous-estime jamais"],"correct":0,"explication":"Les dividendes encaissés depuis l’introduction s’ajoutent à la variation du cours."}],"liens":[{"label":"Fiche Orange Côte d’Ivoire","href":"/societes/ORAC"},{"label":"Fiche Loterie Nationale du Bénin","href":"/societes/LNBB"},{"label":"Fiche BIIC","href":"/societes/BICB"},{"label":"Fiche Bridge Bank Group Côte d’Ivoire","href":"/societes/BBGC"}]},{"titre":"Leçon 7 — Quatre introductions réelles, et un contre-exemple","module":"Module 3 — Évaluer et suivre","categorie":"fundamental","duree_min":14,"sous_titre":"Ce que montrent les opérations de 2022 à 2026, et l’offre de BGFI Holding en Afrique centrale.","resume":"Chacune des quatre dernières introductions à la BRVM éclaire un aspect de l’opération. En Afrique centrale, l’augmentation de capital de BGFI Holding n’a trouvé preneur que pour 36 % des actions offertes.","avertissement":"Ceci n’est pas un conseil en investissement. Investir en actions comporte un risque de perte en capital. Faits arrêtés au 26 novembre 2026.","sections":[{"type":"cas","titre":"Les quatre dernières introductions à la BRVM","contenu":"Toutes les données de ce tableau viennent de la BRVM ou du gouvernement du Bénin. Le montant de Bridge Bank Group Côte d’Ivoire est calculé : les quatre offres totalisent 352,13 milliards FCFA selon la BRVM, dont on retranche les trois autres.","reel":true,"tableau":{"colonnes":["Société","Vendeur","Prix","Montant","Ce qu’il faut retenir"],"lignes":[["Bridge Bank Group Côte d’Ivoire (2026)","Non précisé par la BRVM","6 750 FCFA","67,5 Md FCFA (calcul)","Plus de 17 000 souscripteurs ; admise au compartiment Prestige ; arrangeur Bridge Securities."],["BIIC (2025)","État du Bénin","5 250 FCFA","100,45 Md FCFA","Deuxième plus grosse introduction de l’histoire de la BRVM ; plus de 10 000 souscriptions de particuliers, environ 25 % du montant ; capitalisation de 323,45 Md FCFA à l’introduction."],["Loterie Nationale du Bénin (2024)","État du Bénin","4 800 FCFA","43,2 Md FCFA","Conclue à la borne haute de la fourchette annoncée : 45 % du capital cédés ; visa n° OA/24-01."],["Orange Côte d’Ivoire (2022)","État de Côte d’Ivoire","9 500 FCFA","140,98 Md FCFA","Plus grosse introduction de l’histoire de la BRVM ; offre close par anticipation ; +7,47 % à la première séance."]],"note":"Sources : BRVM (communiqués du 30 décembre 2022, du 28 avril 2025 et de septembre 2026 ; avis de première cotation), gouvernement du Bénin (communiqués de l’État sur les offres LNB et BIIC). Calcul WESTBOURSE : 352,13 − 140,98 − 100,45 − 43,2 = 67,5 milliards FCFA, soit 10 millions d’actions à 6 750 FCFA."}},{"type":"cas","titre":"Le contre-exemple : BGFI Holding à la BVMAC","contenu":"BGFI Holding n’est pas cotée à la BRVM mais à la BVMAC, la bourse de l’Afrique centrale (CEMAC). Son offre était une augmentation de capital : 10 % du capital en actions nouvelles, pour 125,88 milliards FCFA au prix de 80 000 FCFA, soit 1 573 536 actions (dépliant de l’offre de BGFI Holding ; calcul pour le nombre d’actions).\nSeules 566 561 actions nouvelles ont été créées (communiqué de la BVMAC du 7 mai 2026). Rapportées aux 1 573 536 offertes, cela fait un taux de souscription de 36 %, et 45,32 milliards FCFA levés au prix de 80 000 FCFA (calcul). Les nouvelles actions représentent 3,85 % du capital après l’opération : c’est la dilution des anciens actionnaires.\nÀ la première séance, le 7 mai 2026, l’action a été échangée à 82 000 FCFA, +2,5 % par rapport au cours de référence, pour 607 actions échangées. Les deux zones utilisent le « franc CFA », mais ce sont deux monnaies distinctes, de même valeur.","reel":true,"stats":[{"label":"Actions offertes","valeur":"1 573 536","detail":"125,88 Md FCFA ÷ 80 000 FCFA (calcul)"},{"label":"Actions créées","valeur":"566 561","detail":"Communiqué de la BVMAC, 7 mai 2026"},{"label":"Taux de souscription","valeur":"36 %","detail":"566 561 ÷ 1 573 536 (calcul)"},{"label":"Première séance","valeur":"+2,5 %","detail":"82 000 FCFA, 607 actions échangées"}]},{"type":"piege","titre":"Ce que ces cas apprennent","contenu":"Cinq leçons, toutes tirées des chiffres ci-dessus.","points":[{"titre":"Une OPV ne finance pas la société","detail":"Pour Orange CI, la LNB et la BIIC, l’argent est allé à l’État vendeur. Pour BGFI, augmentation de capital, il est allé au groupe."},{"titre":"Le prix unitaire compte pour l’accès","detail":"À 80 000 FCFA, une seule action BGFI coûte plus que dix actions Orange CI au prix de l’offre : le ticket d’entrée écarte une partie des petits épargnants."},{"titre":"La taille du marché limite la taille de l’offre","detail":"Une offre de 125,88 milliards, sur une bourse qui comptait six sociétés cotées, n’a trouvé preneur qu’à 36 %."},{"titre":"Une offre très demandée ne garantit pas la suite","detail":"La LNB, conclue à la borne haute, cotait sous son prix d’offre fin novembre 2026 (leçon 6)."},{"titre":"Les particuliers comptent","detail":"À la BIIC, plus de 10 000 souscriptions de particuliers ont représenté environ un quart du montant."}]},{"type":"retenir","titre":"À retenir","contenu":"Lire une introduction, c’est répondre à cinq questions : qui vend, à quel prix au regard des bénéfices, combien d’actions, pour quelle part du capital, et sur quel marché."}],"quiz":[{"question":"Une banque est introduite par OPV ; sa maison mère vend ses actions pour financer son expansion ailleurs. Les fonds propres de la banque introduite en sortent-ils renforcés ?","options":["Oui, de tout le montant de l’offre","Non, l’argent va à la maison mère qui vend","Oui, de la moitié","Cela dépend du cours de la première séance"],"correct":1,"explication":"Dans une OPV, aucun argent frais n’entre dans les fonds propres de la société : seule une augmentation de capital les renforce directement."},{"question":"BGFI Holding offrait 1 573 536 actions et en a créé 566 561. Quel est le taux de souscription ?","options":["14 %","36 %","64 %","277 %"],"correct":1,"explication":"566 561 ÷ 1 573 536 = 0,36, soit 36 %."},{"question":"Quelle introduction est la plus importante de l’histoire de la BRVM ?","options":["La BIIC","Orange Côte d’Ivoire","La Loterie Nationale du Bénin","Bridge Bank Group Côte d’Ivoire"],"correct":1,"explication":"Orange Côte d’Ivoire, 140,98 milliards FCFA en 2022 ; la BIIC (100,45 milliards) est deuxième."},{"question":"Pourquoi les actions nouvelles de BGFI Holding diluent-elles les anciens actionnaires ?","options":["Parce que le prix a baissé","Parce qu’elles s’ajoutent au capital et réduisent la part de chacun","Parce que la BVMAC l’impose","Elles ne les diluent pas"],"correct":1,"explication":"Les 566 561 actions nouvelles représentent 3,85 % du capital après l’opération : chaque ancien actionnaire détient une part plus petite."}]}],"glossaire":[{"terme":"Introduction en bourse (IPO)","definition":"Offre d’actions au public suivie de leur cotation en bourse."},{"terme":"Offre publique de vente (OPV)","definition":"Vente au public d’actions existantes par leurs détenteurs ; l’argent va aux vendeurs."},{"terme":"Augmentation de capital","definition":"Création d’actions nouvelles ; l’argent va à la société, et la part des anciens actionnaires diminue."},{"terme":"Note d’information","definition":"Prospectus de l’offre, visé par l’AMF-UMOA."},{"terme":"AMF-UMOA","definition":"Autorité des marchés financiers de l’UMOA, régulateur du marché financier régional."},{"terme":"SGI","definition":"Société de gestion et d’intermédiation, intermédiaire agréé pour acheter et vendre des titres."},{"terme":"Flottant","definition":"Part du capital détenue par le public."},{"terme":"Taux de souscription","definition":"Demande reçue divisée par l’offre."},{"terme":"Cours de référence","definition":"Prix de départ de la première séance, en général le prix de l’offre."},{"terme":"PER","definition":"Valorisation divisée par le résultat net : le nombre d’années de bénéfice que l’on paie."},{"terme":"P/B","definition":"Valorisation divisée par les fonds propres ; égal au PER multiplié par la rentabilité des fonds propres."},{"terme":"IRVM","definition":"Impôt sur le revenu des valeurs mobilières, retenu à la source sur les dividendes."},{"terme":"BVMAC","definition":"Bourse des valeurs mobilières de l’Afrique centrale (zone CEMAC)."}]}$wb$::jsonb,
  $wb$<p>Cours natif — ouvrir /formations/academy/introduction-en-bourse-ipo-brvm</p>$wb$,
  true
)
